// Require HTTP success and the typed S verdict; provider availability is separate from local sync.
const ctx = $('Parse Input').first().json;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const hasError = value => Object.hasOwn(value, 'error') || Object.hasOwn(value, 'errors') ||
  (Object.hasOwn(value, 'request_result') && value.request_result !== 'success');
function readResult(nodeName, enabled, booleanField) {
  if (!enabled) return { ok: false, state: 'skipped', error: null };
  const unavailable = { ok: false, state: 'unavailable',
    error: { code: 'api_unavailable', message: nodeName + ' unavailable' } };
  try {
    const response = $(nodeName).first().json;
    if (!object(response) || !Number.isInteger(response.statusCode) ||
        response.statusCode < 200 || response.statusCode >= 300 || hasError(response)) return unavailable;
    const body = response.body;
    if (!object(body) || hasError(body)) return unavailable;
    if (body.state === 'skipped' && body.ok === false && !Object.hasOwn(body, booleanField)) {
      return { ok: false, state: 'skipped', error: null };
    }
    if (body.ok !== true || typeof body[booleanField] !== 'boolean' ||
        body.state !== (body[booleanField] ? 'verified_true' : 'verified_false')) return unavailable;
    if (body[booleanField] === false && (!Array.isArray(body.events) || body.events.length !== 0)) return unavailable;
    const result = { ok: true, state: body.state, value: body[booleanField], error: null };
    // Missing or malformed event metadata is unknown, never an authoritative empty list.
    if (Array.isArray(body.events) && body.events.every(name => typeof name === 'string' && name.trim())) {
      result.events = body.events;
    }
    return result;
  } catch (error) {
    return unavailable;
  }
}
// Dead by design: this workflow never has eBas authority or a PNR, even from a legacy caller.
const ebas = { ok: false, state: 'skipped', error: null };
const startgg = readResult('Start.gg Check', ctx._runStartgg === true, 'isRegistered');
const startggData = startgg.ok ? { registered: startgg.value } : {};
if (Object.hasOwn(startgg, 'events')) startggData.events = startgg.events;
return [{ json: {
  checkin_id: ctx.checkin_id, attempt_id: ctx.attempt_id,
  member: null, startgg: startgg.ok ? startgg.value : null,
  ...(Object.hasOwn(startgg, 'events') ? { events: startgg.events } : {}),
  _ebasOk: false, _startggOk: startgg.ok,
  _ebasState: ebas.state, _startggState: startgg.state,
  _ebasData: {}, _startggData: startggData,
  _ebasError: null, _startggError: startgg.error,
  _startggEnabled: ctx._runStartgg === true,
  fetched_at: new Date().toISOString(),
} }];

