// A successful provider response cannot stand in for a canonical local-write acknowledgement.
const ctx = $('Combine Results').first().json;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function acknowledge(nodeName, enabled, source, expectedOk, expectedState) {
  if (!enabled) return 'skipped';
  try {
    const response = $(nodeName).first().json;
    if (!object(response) || !Number.isInteger(response.statusCode) ||
        response.statusCode < 200 || response.statusCode >= 300 ||
        Object.hasOwn(response, 'error') || Object.hasOwn(response, 'errors') ||
        (Object.hasOwn(response, 'request_result') && response.request_result !== 'success')) return 'failed';
    const body = response.body;
    if (!object(body) || Object.hasOwn(body, 'error') || Object.hasOwn(body, 'errors') ||
        (Object.hasOwn(body, 'request_result') && body.request_result !== 'success')) return 'failed';
    if (body.state === 'stale_rejected') return 'stale';
    if (body.checkin_id !== ctx.checkin_id || body.source !== source || body.ok !== expectedOk ||
        typeof body.updated !== 'boolean' ||
        (body.state != null && body.state !== expectedState)) return 'failed';
    if (expectedOk) return body.updated === true ? 'ok' : 'failed';
    return body.updated === false && ['unavailable', 'skipped'].includes(expectedState) ? 'ok' : 'failed';
  } catch (error) {
    return 'failed';
  }
}
const startggSync = acknowledge('Report Start.gg Result', ctx._startggEnabled, 'startgg',
  ctx._startggOk, ctx._startggState);
// The retained eBas callback has no authority; its acknowledgement cannot poison Start.gg sync.
const localSync = startggSync;
const startggState = ['failed', 'stale'].includes(startggSync) ? 'unavailable' : ctx._startggState;
const verified = startggSync === 'ok' && ctx._startggOk === true;
return [{ json: {
  checkin_id: ctx.checkin_id, attempt_id: ctx.attempt_id,
  member: null, startgg: verified ? ctx.startgg : null,
  ...(verified && Object.hasOwn(ctx._startggData, 'events') ? { events: ctx._startggData.events } : {}),
  results: { ebas: 'skipped', startgg: startggState, attempt_id: ctx.attempt_id },
  local_sync: localSync, local_sync_sources: { ebas: 'skipped', startgg: startggSync },
  integration_complete: verified,
} }];

